  str_book_title_saiji_20106 = "Duri Bergerak II",
  str_book_title_saiji_20107 = "Pengadilan Ditunda I",
  str_book_title_saiji_20108 = "Pengadilan Ditunda II",
  str_book_info1001 = "Tertidur di bawah tanah selama 17 tahun, kamu dan Soroz saling tergantung. Hasil pemeliharaan rutin menyatakan bahwa upaya untuk mengaktifkan Colossus ini kali ini pasti akan gagal, tak ubahnya seperti sekian banyak upaya yang sudah dilakukan sebelumnya...",
  str_book_info1002 = "Namun, keadaan hari ini sepertinya berbeda akibat adanya seorang penyerang yang muncul tiba-tiba. Sebagai Caelestite, kamu punya kemampuan istimewa berupa pengetahuan, dan dengan bakat ini, kamu menanggung beban untuk membalaskan dendam sukumu...",
  str_book_info1003 = "Tak ada lagi kedamaian di Colossus. Dengan adanya serangan dari Kraken, Eclipsite papan atas, tugasmu untuk menembus masuk jadi makin sulit. Bisakah kamu membuktikan kapabilitas yang harus dimiliki Navigator saat menghadapi musuh kuat untuk pertama kalinya?",
  str_book_info1004 = "Tepat saat kamu menginjakkan kaki ke dunia baru, Eclipsite bergerak memburumu. Bagaimana bisa mereka muncul di sini? Waktumu hampir habis, jadi kamu harus kembali ke Colossus dan mencari jalan keluar lain...",
  str_book_info1005 = "Saat menghadapi panel kontrol yang familiar, kamu memutuskan untuk melibatkan Vice dalam urutan penyalaannya. Kamu menunjukkan cara bermainnya kepada Vice dan bersiap menyelesaikan duet bersama.",
  str_book_info1006 = "Saat menghadapi panel kontrol yang familiar, kamu memutuskan untuk melibatkan Vice dalam urutan penyalaannya. Kamu menunjukkan cara bermainnya kepada Vice dan bersiap menyelesaikan duet bersama.",
  str_book_info1007 = "Saat menghadapi panel kontrol yang familiar, kamu memutuskan untuk melibatkan Vice dalam urutan penyalaannya. Kamu menunjukkan cara bermainnya kepada Vice dan bersiap menyelesaikan duet bersama.",
  str_book_info1008 = "Dengan bantuan Vice, akhirnya kamu berhasil mengaktifkan Colossus. Saat daya mulai mengalir seperti aliran Aurora, Colossus perlahan naik ke permukaan. Tunggu saja sebentar lagi dan kamu akan terlepas dari bahaya.",
  str_book_info1009 = "Setelah mengaktifkan Colossus, ingatan dari masa lalu pun berhamburan kembali; hari itu adalah hari saat masyarakatmu dihancurkan di Eraveil 17 tahun lalu. Di tengah semua gambar yang kamu lihat, muncul satu sosok yang tak akan pernah kamu lupakan...",
  str_book_info1010 = "Bahaya sama sekali belum sirna. Dengan kalahnya Sand Kraken, High-level Eclipsite bernama Nozard bersumpah akan menghancurkanmu, dan makin banyak musuh mulai berkumpul di sekitar Soroz, siap menamatkan riwayatmu sementara Soroz masih memanaskan diri...",
  str_book_info1011 = "Setelah pemanasan, energi Soroz sekali lagi mengalir melalui tubuhnya. Ia mengembangkan sayapnya dan membawamu keluar dari cengkeraman kegelapan, kembali ke angkasa. Musuh tercerai-berai bak debu, gemetaran di tengah deru Soroz yang kini bangkit kembali...",
  str_book_info1012 = "Soroz terpaksa mendarat darurat di hutan belantara setelah terluka akibat pertempuran dan terbang untuk pertama kalinya setelah sekian lama... Saat kamu dan Vice sedang berdebat, para Eclipsite menyerang...",
  str_book_info1013 = "Rediesel Wrench... Sekelompok penyintas sinting yang tak sengaja kamu temui ini benar-benar membuka matamu tentang cara bertahan hidup, persahabatan, dan menjalani hidup kita sendiri. Lebih spesifiknya, masakan mereka benar-benar payah.",
  str_book_info1014 = "Di zona layak huni antara terang dan gelap, manusia bertarung untuk melindungi tempat tinggal mereka. Seperti kata Charon, selain Illumina, masih ada banyak lagi Aurorian dan manusia di luar sana yang bertarung demi melindungi hal-hal yang berarti bagi mereka.",
  str_book_info1015 = "Nozard muncul lagi, dan kali ini dia mengomando lebih banyak lagi Eclipsite dibandingkan yang sudah-sudah. Barak sementara, Undercity 28, tinggal puing-puing akibat serangan kejutan. Seiring dengan jatuhnya barak itu, babak baru pun dimulai...",
  str_book_info1016 = "Nozard masih gencar mengejar. Untuk mengelabui musuh agar kamu bisa mundur, Charon membiarkan dirinya dikepung oleh Eclipsite. Dia menekan tombol penghancur diri, Red Key, agar kamu tidak berbuat nekat. Kamu tidak punya pilihan selain pergi...",
  str_book_info1017 = "Undercity 28 luluh lantak menjadi puing akibat ledakan besar. Saat kamu meratapi ketiadaan Charon, muncul suatu sosok. Ternyata sosok itu adalah Charon sendiri, yang rupanya berhasil menyelamatkan diri dalam akhir sempurna yang mengagumkan...",
  str_book_info1018 = "Saat kamu baru saja akan istirahat, kamu menerima panggilan minta bantuan yang tampaknya berasal dari rekan senegaramu. Setelah tiba di tujuan, kamu diserang oleh Colossus Guardian, Philex dan Vani, yang sepertinya dikendalikan oleh suatu kekuatan yang lebih besar...",
  str_book_info1019 = "Dengan bimbingan Mendelson, kamu berhasil mencapai jembatan dan mengalahkan Tabaad, sementara Hiiro melancarkan pukulan terakhir. Zakura melintas menyapu angkasa dengan cherry blossom, dan pemandangan memesona ini adalah hal terakhir yang diingat Mendelson...",
  str_book_info1020 = "Menurut kata-kata terakhir Mendelson, kamu harus mencegah musuh bernama Schummer agar tidak menemukan item pertama: Think Tank Module. Ini pertama kalinya kamu bertandang ke Lumopolis, pusat peradaban Astra.",
  str_book_info1021 = "Karena kamu tidak punya akses ke Lumopolis, kamu harus lewat Lower Lumopolis. Ini mungkin sama sekali tidak seperti yang kamu bayangkan. Mara bahaya bergelayut di udara. Perjalanan ini mungkin akan dipenuhi kendala.",
  str_book_info1022 = "Berkat surat perintah dari Vice, kamu disambut langsung oleh Carleen, sang Kapten di Lumopolis Guardian. Walau gadis muda yang pelit senyum ini dulunya adalah teman sekolah Vice, dia mengalihkan pandangan dan seperti tak memperhatikanmu sedikit pun...",
  str_book_info1023 = "Si pembuat onar, Shelt dan Shire, kabur ke Uptown tetapi kamu berhasil mencegat mereka tanpa ampun. Kedua Eclipsite itu sudah siap bertarung, tetapi mereka sama sekali tak tahu akibat yang akan mereka tanggung...",
  str_book_info1024 = "Kamu memberikan ringkasan rencana Schummer dan insiden Lumopolis di tempat persidangan, tetapi para Officer Illumina Federation tidak bisa memberikan bantuan karena berbagai alasan. Sepertinya kamu harus menangani sendiri pertarungan memperebutkan modul berikutnya.",
  str_book_info1025 = "Saat sampai di tempat disembunyikannya Component kedua, seperti yang ditampilkan dalam datamu, kamu tiba-tiba dikepung oleh sensasi aneh antara ilusi dan suara yang seperti menyihir—gema misterius yang membuatmu dipenuhi perasaan takzim...",
  str_book_info1026 = "Untuk memperoleh modul kedua, kamu membangun tautan dengan Colossus lain yang sudah lama mati. Penampakan Caelestite terdahulu muncul di hadapanmu, dan pikiran mereka mulai meresap ke dalam pikiranmu seperti simfoni yang mengalun lambat.",
  str_book_info1027 = "Untuk menyelamatkan Gronru, kamu membuat kesepakatan dengan Schummer dan menyerahkan modul kedua. Tanpa terduga, Schummer benar-benar memenuhi janjinya, semata karena dia adalah rekan senegaramu sehingga dia agak kasihan kepadamu...",
  str_book_info1028 = "Modul terakhir berada di Whispering Corridor yang misterius, tetapi waktu makin menipis dan kamu harus bergerak cepat. Tempat itu adalah bunker bawah tanah yang berisi benda-benda misterius, dan kamu sama sekali tak tahu apa yang akan kamu temui di sana...",
  str_book_info1029 = "Jalan masuk menuju Whispering Corridor menelan habis cahaya matahari seperti monster tanpa nama, dan tangga spiralnya seperti memberimu firasat. Kalau Schummer sudah sampai di sana, kamu harus bergegas...",
  str_book_info1030 = "Gertzurde, yang bekerja sama dengan Shelt untuk mencuri modul pertama, akhirnya berhasil kamu kalahkan. Setelah mengetahui kebenaran di balik kematian Shelt, matanya terbelalak tak percaya, dan rasanya seakan-akan sebagian dari dirinya mati sementara bagian lainnya mulai menyala...",
  str_book_info1031 = "Di kedalaman Whispering Corridor, Schummer bergerak untuk melancarkan serangan mematikan, tetapi Gertzurde menghadangnya di depanmu dengan penuh keyakinan. Wajahnya memucat seiring dengan terkurasnya aliran kehidupan dari dirinya, tetapi tak ada waktu untuk meratap atau bersimpati. Masih ada tugas yang harus dilakukan.",
  str_book_info1032 = "Dengan membawa ketiga modul, Schummer memimpin Black Colossus untuk menyerang Lumopolis habis-habisan. Walau serangan itu berhasil dibendung oleh benteng Lumina Shield, suara terompet hujatan telah berkumandang di udara...",
  str_book_info1033 = "Dengan bekerja sama dengan Officer dari Illumina Federation, Mara Sol si sandworm raksasa yang mencoba menyerang Lumopolis berhasil dikalahkan telak. Musuh memang tidak menyerang lagi untuk sementara ini, tetapi krisis yang lebih besar akan segera timbul...",
  str_book_info1034 = "Schummer yang dipenuhi dendam menyerang Soroz, dan kamu terpaksa mengesampingkan krisis di Lumopolis dan segera kembali ke Colossus. Adegan ini harusnya sudah berakhir 17 tahun lalu; Colossus hitam-putih itu kembali terjebak dalam pertempuran...",
  str_book_info1035 = "Seorang pria misterius bertudung berdiri di sebelah Schummer, si Great Aviduz. Karena ejekan Vivian, dia pun menunjukkan wajahnya, dan sebuah nama yang berhubungan erat dengan Illumina Federation: Forsakin...",
  str_book_info1036 = "Sebelum bisa bertanya lebih banyak, Schummer sudah terisi penuh, dan kekuatannya yang tak dikenal membuat semua orang terhempas ke tanah. Menghadapi kekuatan begitu besar yang tak bisa dihentikan, Vivian memutuskan mengambil langkah berisiko...",
  str_book_info1037 = "\"Orang-orang di sini juga sangat cerewet. Mereka hanya bisa bicara omong kosong saja. Bla, bla, bla, bla, bla...\"",
  str_book_info1038 = "Atas perintah Faust, Vice mengambil benda aneh yang disebut \"Seed\" itu darimu, yang katanya merupakan benda yang mengubah berbagai makhluk menjadi Apostles of Darkness dan merupakan perantara untuk memanggil kekuatan jahat...",
  str_book_info1039 = "\"Kenapa tidak kauterima saja kelemahanmu? Kenapa kau tidak mau berlutut di hadapan kekuatan sejati?\"",
  str_book_info1040 = "Lumina cannon Damocles, senjata pamungkas Lumopolis, menyerang Aviduz sambil mengeluarkan deru mengerikan, bahkan walaupun itu mungkin membahayakan kota...",
  str_book_info1041 = "Sinar yang memancar dari Damocles berpindah tiba-tiba, dan Carleen, yang sisa Lumina-nya tinggal sedikit, tampaknya tidak mampu memandunya sendirian sampai selesai. Pada saat itu, Schwartz, City Lord Lumopolis, muncul di belakangnya. Bersama-sama, mereka berdua melancarkan pukulan terakhir terhadap Schummer.",
  str_book_info1042 = "Berkat tekanan mental darimu, Aviduz tidak berhasil menghindari sinar itu dan tertembus dalam sekejap. Waktu seakan berhenti, dan semua orang diam mematung di posisinya, menyaksikan akhir Black Colossus...",
  str_book_info1043 = "Fakta bahwa ada High-Level Eclipsite yang tinggal di Dungeon No. 80 tepat di tepi batas Eternal Night sangat mengejutkan. Selain di luar dugaan semua orang, kemunculannya juga mengusik Vice dan Navigator yang sedang berusaha memperbaiki Soroz.",
  str_book_info1044 = "Dia pernah melewatkan kesempatannya dan kali ini dia tak bertekad untuk menyerah. Bisakah dia menyadarkan temannya di saat pikiran rekan seperjuangannya diselimuti amarah dan kebencian tatkala kenangan akan hal yang ingin dia lindungi serta ikatan dengan teman-temannya sudah sirna?",
  str_book_info1045 = [[
Meski bila nanti dunia sudah diselimuti kegelapan dan tak ada lagi secercah cahaya, akulah yang akan menjadi cahaya dan menghalau kegelapan.
Itulah jalan yang dipilih Reinhardt. Dia memilih untuk menjadi cahaya yang menerangi setiap sudut, menghadirkan harapan di tengah-tengah keputusasaan.]],
  str_book_info2001 = "Dikepung oleh Four Angels, sepertinya tidak ada jalan keluar bagi Brock dan Jona... Namun, tepat pada saat itu, Jona berhasil menemukan jalan keluar istimewa: melompat keluar dari Lumopolis! Apa pun hasilnya, setidaknya mereka berhasil keluar dari Lumopolis...",
  str_book_info2002 = "Setelah berhasil meloloskan diri dari Lumopolis, Jona dan Brock bertemu kembali dengan pasukan Rediesel Wrench. Menghadapi para pengejar itu, mereka melontarkan satu kalimat lelucon pilihan dan melenggang sombong, kemudian menghilang di balik pasir kuning yang bergulung-gulung...",
  str_book_info2003 = "Bowlinger mengaktifkan fungsi penghancuran diri dan Sharona berhasil lolos dengan susah payah sambil memanggul Philyshy di pundaknya. Kedua musuh itu akhirnya berdamai, dan bersama-sama, mereka mengatasi ancaman tersembunyi yang mengancam Gannon City. Philyshy menguap lagi, tetapi Sharona tidak lagi menegurnya, dan mereka berdua pun lolos dari ledakan itu.",
  str_book_info2004 = "Setelah pertempuran mendebarkan, Connolly memperoleh teman kecil yang merepotkan dan dia jadi punya pemahaman baru akan kata \"rumah\". Hari itu memang hari yang biasa-biasa saja di Holiday Cafe yang juga biasa-biasa saja, tetapi bagi Connolly, hari itu menjadi kepingan berharga dalam kehidupan sehari-harinya...",
  str_book_info2005 = "Northland, bentang daratan es penuh keajaiban tempat bintang-bintang bersinar jatuh dari langit menghiasi danau sebening kristal, di mana salju paling murni menyelimuti hutan lebat dan dataran tak terbatas. Sebuah istana yang menakjubkan berdiri tegak di tengah angin dingin, merentangkan tangannya yang ramping dan putih bagai bidadari yang mengulurkan tangan untuk menyentuh Aurora.",
  str_book_info2006 = "Upaya Carleen akhirnya membuahkan hasil saat dia menancapkan tombaknya melalui rintangan berat, dan saat Eclipsite jatuh, dia akhirnya menyelesaikan trial Betlehem. Jalan Guardian itu sulit dan sepi, dan hanya diperuntukkan bagi mereka yang memiliki kekuatan sejati. Namun, selama seseorang melihat ke atas dan menatap Aurora yang indah—hanya dengan begitu maknanya yang tak terbantahkan dapat dipahami.",
  str_book_info1051 = [[
Forsakin dan Schummer berdiri di hadapan cangkang penyembuhan.
Forsiken memberitahunya bahwa selama dia melepaskan semua yang diperlukan untuk menjadi seorang Celestite, dia bisa mendapatkan lebih banyak kekuatan.
Yang dimaksud Schummer tentang ini adalah, dia sudah sejak lama menyerah untuk menjadi seorang Caelestite...]],
  str_book_info1052 = "Demi mengungkap keberadaan Schummer dan menemukan cara untuk memperbaiki Soroz, kau kembali ke rumah para Caelestites—\nEraveil",
  str_book_info1053 = [[
Akhirnya, jauh di dalam Eraveil, kau menemukan Aviduz yang jatuh.
Forsakin sudah lama menunggu di sana, dan sepertinya dia ingin mengatakan sesuatu padamu.
Atau apakah dia hanya... bermain-main dengan waktu?]],
  str_book_info1054 = [[
Schummer yang sudah bangkit melahap dengan rakus Eclipsite di sekitarnya.
Meskipun rasanya sangat menjijikkan, tekad untuk menuntut balas dendam mendorongnya untuk mengabaikan semua prasangka tentang rasa sakit.]],
  str_book_info1055 = [[
Setelah memperoleh kekuatan baru, Schummer ingin gurunya menerima hadiah ini, tapi dia terkunci di balik pengekangan yang tak terhindarkan.
Namun, ikatan semacam itu tidak bisa menghentikan Schummer, dan dia sangat yakin bahwa para Caelestite pada akhirnya akan berdoa kepadanya untuk kesempatan kedua.]],
  str_book_info1056 = [[
Melalui penaklukan di dalam dan di luar, Eraveil pun takluk.
Para Eclipsite langsung menyerbu masuk, menyatakan kedatangan besar dari Eclipse.]],
  str_book_info1057 = [[
Didorong oleh keinginan yang tak terkendali, Schummer menerobos batas Seed, dan Forsakin akhirnya mencapai tujuannya.
Dia mengambil Seed dari Schummer tanpa ragu-ragu dan pergi.]],
  str_book_info1058 = [[
Schummer memerintahkan Eclipsite untuk membunuh semua orang saat mereka sibuk mengambil Module.
Namun, karena dia kehilangan Seed-nya, dia langsung dikelilingi oleh Eclipsite dan tewas di tengah lautan kekacauan gelap yang bergerak.
Akhir hidupnya mencerminkan penderitaan yang dialami rakyatnya tujuh belas tahun yang lalu.]],
  str_book_info1059 = [[
Di saat-saat terakhirnya, sebagian dari kesadaran Schummer memasuki pikiranmu.
Kamu menyaksikan bayang-bayang Eclipse. Meskipun hanya sesaat, sejauh mana kekuatan yang kamu rasakan tidak perlu dipertanyakan lagi...]],
  str_book_info1060 = "Mengiringi suara keras, pintu di hadapanmu itu perlahan terbuka. Rahasia-rahasia yang terkubur di bawah Eraveil menunggu untuk kauungkap.",
  str_book_info1061 = "Special Attacker diaktifkan untuk menangani Eclipsite, tetapi Aurorian juga jadi targetnya. Vice terkena serangannya saat mencoba untuk melindungimu.",
  str_book_info1062 = "Kau tiba di area inti jauh di dasar bawah tanah dan menemukan Circular System yang mengontrol seluruh pangkalan. Mesin aneh ini mungkin tahu cara menyelamatkan Vice yang mengalami Hibernation.",
  str_book_info1063 = [[
Obelisk of Return muncul secara mengejutkan dan memperlihatkan wujud aslinya.
"White Tower ini tidak pernah dimaksudkan untuk berada di sini. Seharusnya ia berada... di tempat yang jauh lebih tinggi."]],
  str_book_info1064 = "White Tower telah menjadi bangunan tertinggi di Eraveil. Menjulang kokoh setinggi ini, kau bisa melihat seluruh dunia dari menara ini.",
  str_book_info1065 = "Perubahan geologis yang terjadi baru-baru ini membuat jalan menuju Chord Zone menjadi terjal dan berbatu. Terowongan yang dipenuhi jebakan ini sangat menyulitkan langkahmu. Tapi, demi kesembuhan Vice, kau harus mengatasi kesulitan apa pun yang menghalangi jalanmu.",
  str_book_info1066 = "Barton mendapatkan kekuatan baru dari Chord Link, yang memungkinkannya untuk berhadapan dengan Forsakin sekali lagi dan membalikkan keadaan. Berkat bantuannya, kau bisa menghalau Forsakin dan memasukkan Vice ke Chord Link, berharap dia bisa disembuhkan...",
  str_book_info1067 = "Eraveil mengalami krisis yang belum pernah terjadi sebelumnya. Obelisk of Return yang dikepung oleh Eclipsite membuatmu teringat pada hari Eraveil diserang. Namun, kali ini berbeda. Teman dan sekutu dari segala penjuru telah datang untuk membantumu.",
  str_book_info1068 = "Vice yang mengalami Hibernation dimasukkan ke dalam Chord Link untuk menjalani perawatan. Beri dia waktu dan percayalah bahwa dia akan siuman.",
  str_book_info1069 = "Kau dan Carleen telah menenun kepompong menggunakan lapisan pertahanan Obelisk of Return untuk melindungi Vice yang berada di dalam Chord Link dan untuk memastikan bahwa dia akan bangun sesuai rencana. Sekaranglah saatnya untuk memecahkan kepompong itu.",
  str_book_info1070 = "Sekutumu menahan para Eclipsite di luar menara untuk memastikan operasi itu berjalan lancar. Pertempuran antara Queen of the North, yang telah datang dari jauh, dan Figelo pun pecah. Kini setiap detik sangatlah berarti. Cari kesempatan demi membalikkan keadaan dan membawa kemenangan serta harapan untuk pertempuran ini.",
  str_book_info1071 = "Vice yang telah terbangun dari Chord Link tampaknya mendapatkan kekuatan baru. Pikiran kalian terhubung pada saat ini. Kau telah melindunginya selama ini, dan sekarang, dia akan berjuang untukmu.",
  str_book_info1072 = "Pertempuran Eraveil memang sudah berakhir untuk saat ini, tapi setiap orang memiliki pendapat berbeda tentang apa yang harus dilakukan pada Obelisk of Return. Pada akhirnya, mereka berhasil mencapai kesepakatan—Obelisk of Return adalah milik Eraveil dan kaum Caelestite.",
  str_book_info1073 = "Anda bertemu dengan Sean, Crow, dan Zhao di pusat medis Illumina. Mereka datang dari kota terpencil bernama Twilight yang terletak di luar garis pertahanan Illumina...",
  str_book_info1074 = "Empat peneliti dari Dewan Sains rahasia Illumina sedang menunggu Anda. Bagaimana pertemuan rahasia ini akan mengubah nasib Anda dan Soroz?",
  str_book_info1075 = "Anda melihat Soroz lagi di ruang data. Itu ada di depan Anda, tetapi Anda tidak bisa menyentuhnya. Bahkan kedekatan itu salah.",
  str_book_info1076 = "Menurut catatan kuno, Colossi kembali dari langit. Dunia telah lama menjadi asing, membuat mereka tidak punya pilihan selain mencari jejak masa lalu.",
  str_book_info1077 = "Ketika Aurorastorm melonjak tak terkendali, para kesatria merobek langit merah seperti komet perak cemerlang. Dengan kesopanan Lumo Nobles yang tidak lagi menjadi pertimbangan, para kesatria tangguh ini mengenakan baju besi berpaku mereka untuk membela rakyat.",
  str_book_info1078 = "Anda memasuki Twilight dan tidak tahu harus mencari ke mana. Para tunawisma berkeliaran di jalanan, pedagang menjajakan dagangannya, dan ksatria Lumo serta tentara Illumina berjalan berdampingan di jalanan.",
  str_book_info1079 = "Sean memutuskan untuk menantang Axelia untuk melihat siapa yang bisa mengalahkan lebih banyak Eclipsites. Pada akhirnya, Axelia menang!",
  str_book_info1080 = "Colossus ini telah terkubur di sini selama bertahun-tahun sehingga hampir menyatu seluruhnya dengan bebatuan di sekitarnya. Raksasa yang pernah terbang tinggi di langit biru tidak akan pernah lagi melebarkan sayapnya...",
  str_book_info1081 = "Saat Anda kembali, Wraith yang belum pernah Anda temui sebelumnya menghalangi Anda. Dia memiliki kekuatan besar dan motif yang aneh. Dia sepertinya ingin menghancurkan semua \"keinginan\" di dunia.",
  str_book_info1082 = "\"Kita bertemu lagi, Caelestite. Aku tidak akan menahan diri karena kamu telah datang dan menyerahkan dirimu kepadaku.\"",
  str_book_info1083 = "Untuk menyelesaikan eksperimennya dan mengumpulkan data, Forsakin memutuskan untuk menggunakannya Vice untuk mengungkap rahasia Chord Link. Saat Anda mencoba menghentikannya, Anda terjepit ke tanah oleh hewan peliharaan yang dibawanya kemana-mana.",
  str_book_info1084 = "Yingel memainkan kartu trufnya melawan Forsakin dan Helios—dia mengancam Forsakin dengan penghancuran Chord Link. Menghadapi penghinaan dan penghinaan dari pihak lain, Yingel menarik pelatuknya.",
  str_book_info1085 = "Berpikir bahwa lab telah dihancurkan, Forsakin buru-buru meninggalkan sanderanya untuk menyelamatkan lab, hanya untuk menyadarinya Yingel telah menipunya.",
  str_book_info1086 = "Forsakin menggunakan tiga metode peningkatan berbeda untuk berhasil mengubah Helios menjadi eksistensi terkuat. Sekarang saatnya menguji stabilitas subjek dengan membunuh sesuatu.",
  str_book_info1087 = "Latihan Militer Gabungan diadakan sesuai jadwal, dan peserta dari Lumopolis, Illumina, Twilight, dan semua tempat lainnya berkumpul di sini untuk memperebutkan mahkota.",
  str_book_info1088 = "Melawan gelombang Eclipsites di Battle Simulator, tim Leo masih berhasil tampil sebagai pemenang, mengejutkan semua orang dengan kekuatan mereka.",
  str_book_info1089 = "Anggota tim Leo tampaknya telah mengungkap kelemahan dalam pertempuran perebutan bendera terakhir. Yingel dengan tegas menangkap kesempatan singkat ini untuk mengakhiri pertempuran.",
  str_book_info1090 = "Tim Yingel, sang juara, kirim Axelia untuk berpartisipasi dalam pertandingan eksibisi dengan Reinhardt. Arus bawah melonjak di bawah suasana tempat yang tampaknya damai.",
  str_book_info1091 = "Meskipun Anda menghentikan Figerald, Wraith misterius mengambil konsol inti Guardian One dan mengatakan sesuatu yang tidak jelas di depan semua orang. Siapa dia?",
  str_book_info1092 = "Di ruang interogasi di Illumina, kasus Reinhardt Pengkhianatan menjalani penyelidikan internal ketiga. Marsekal Agung Reinhardt yang dulunya dihormati, kini diborgol, menatap para penonton dengan diam.",
  str_book_info1093 = "Sebagai Grand Marshal baru, Wrath, membuat masuk dengan megah, ia dikelilingi oleh Legiun Pengawal dan senjata canggih: Engine VII. Prajurit-pun kagum dengan keanggunannya yang tak terbendung, namun berbagai emosi bercampur aduk di hatinya.",
  str_book_info1094 = "Lumpur itu terus-menerus menggerogoti tanah, mengeluarkan suara retak yang memekakkan. Gundukan tanah di sekitarnya runtuh, vegetasi layu, dan bau menyengat memenuhi udara. Rasanya seperti jaring besar yang menjebak makhluk tak berdosa.",
  str_book_info1095 = "Di tengah rawa yang cepat menyebar, mulut merah darah dari Eclipsite tiba-tiba muncul. Ia mengamuk dengan liar, bersiap untuk melahap baik daratan maupun para Aurorian. Para prajurit panik, berhamburan ke segala arah.",
  str_book_info1096 = "Tenggelam dalam kegelapan yang tak terbatas, Wrath hanya memiliki cahaya redup di sekelilingnya untuk diandalkan. Itu adalah benih yang tertanam di punggungnya, seperti bor, menguras kekuatan hidupnya tanpa henti. Semakin lemah dia, semakin mempesona kilauan benih itu.",
  str_book_info1097 = "Ekspansi biji itu terbentang seperti mekarnya bunga duri yang indah dalam bentuk Wrath. Dia merasakan sensasi tergelitik, seperti rantai besi yang semakin mengencang di sekelilingnya, seolah-olah itu adalah hukuman atas duel yang telah hilang.",
  str_book_info1098 = "Meskipun Axelia tidak merasakan sakit fisik, penderitaan emosional secara halus meningkat setiap kali dia menyaksikan seorang prajurit jatuh. Satu, dua... dia menghitung jumlah kematian secara diam-diam, menciptakan ilusi bahwa dia telah mati sebanyak sebelas ribu, seratus, dan sebelas kali sendiri.",
  str_book_info1099 = "Di langit biru, beberapa kilatan cahaya putih yang mempesona berlalu. Joselyne, di atas kuda perang putih salju dan mengayunkan pedang tajam, melaju bersama Lumo Skyriders, menuju rawa-rawa. Langit bergema dengan derap kuda.",
  str_book_info1100 = "Navigator mengemudikan Colossus ke lokasi yang ditentukan untuk menjalankan misi. Setelah Colossus terbang ke ketinggian yang aman untuk turun akhir, Caelestites dan Eclipsites mulai turun dari langit. Apakah ini mimpi, atau ini benar-benar pernah terjadi sebelumnya?",
  str_book_info1101 = "Di langit yang diwarnai merah oleh matahari terbenam, melalui lapisan awan dan kabut, sebuah lubang hitam yang bisa menelan segalanya mengawasimu. Sepertinya ia mencoba memberitahumu sesuatu, dan kamu menyadari bahwa ia telah meninggalkan tanda hitam gelap dalam pikiranmu setelah kamu bangun.",
  str_book_info1102 = "Banyak pilar batu beku tampaknya tumbuh menuju langit. Sejenis kekuatan tampaknya membimbing mereka ke dalam suatu bentuk di udara. Mengapa pemandangan seperti ini muncul dalam pikiran seorang Illuminan yang hampir tidak pernah meninggalkan rumah?",
  str_book_info1103 = "Suatu hari, satu tahun... tiga tahun, dan kemudian sepuluh tahun... Di era perang itu, Ulysses muda mencari ruang bukti untuk harapan bertahan hidup Aurorian—harapan yang datang dari nama yang telah dihapus dari sejarah Illumina.",
  str_book_info1104 = "Setelah 40 tahun penelitian, 20 tahun di antaranya dihabiskan untuk mengkompilasi database gen khusus, gudang ini dipenuhi dengan ciptaan Ulysses yang disiapkan khusus untuk saat ini untuk melawan musuh.",
  str_book_info1105 = "Musuh-musuh berlarian di Kota Gannon untuk mencari dan mengeliminasi Caelestite. Tepat ketika mereka mendekati Caelestite, teman kecil dan tak mencolok dari Caelestite itu memblokir serangan berat dari musuh untuk Caelestite tanpa ragu-ragu.",
  str_book_info1106 = "\"Jangan biarkan mereka mengendalikanmu! Kebijaksanaan tidak memiliki batasan!\" teriak Algol sambil pikirannya bekerja dengan kecepatan tinggi bersama Bool. Dia ingin memberi tahu semua orang bahwa mereka tidak perlu hidup dalam dunia yang terus-menerus diancam oleh hal yang tidak diketahui.",
  str_book_info1107 = "Perjalanan selalu misterius dan magis saat bepergian bersama Lady Victoria. Dia mengatakan bahwa sekarang Sungai Pristine telah terbangun dan Eoria perlu memulai bab baru, keberadaan khusus itu diperlukan untuk membimbing semua orang dengan cara yang sama.",
  str_book_info3060 = "Pukulan telak diberikan! Smokey melompat tinggi! Sebelum ada yang sempat bereaksi, bola voli itu melesat melintasi lapangan bagaikan peluru yang ditembakkan dari laras pistol, langsung mengenai lawannya!",
  str_book_info3061 = "Kompetisi aneh ini tiba-tiba berubah menjadi pertempuran senjata air, dan semua orang bergabung!",
  str_book_info3062 = "Ujian terakhir The Ocean Sovereign adalah pertunjukan di tepi pantai! Para Aurorian bergiliran tampil di atas panggung, dan akhirnya, trio Smokey, Carleen, dan Vice—\"Kiss of the Manticore\"—menampilkan pertunjukan memukau yang menggetarkan seluruh penonton.",
  str_book_info3063 = "Tanda-tanda krisis masih ada, dan Beryl tiba-tiba menghilang! Ketika akhirnya kau berhasil menemukannya lagi, dia berada di dunia yang berbahaya!",
  str_book_info3064 = "Ketika sepertinya sudah tak ada harapan lagi, Raphael melompat dari tebing dan menangkap Beryl di udara. Malaikat benar-benar bisa terbang!",
  str_book_info3065 = "Setelah Raphael menangkap Beryl, dia menggunakan jetnya untuk memperlambat kejatuhan mereka. Bagaimana mungkin ada orang yang meninggalkan temannya karena sesuatu yang sepele seperti bahaya mematikan?",
  str_book_info3066 = "Bonacie membawakan melodi terlarang di permukaan laut untuk ditampilkan oleh Holy Avatar-nya. Saat mereka melakukannya, kastel yang tertidur di dasar laut perlahan muncul di belakangnya, dan sebuah meteorit besar jatuh dari langit, mengarah langsung ke para hero kita, pantai, dan penginapan!",
  str_book_info3067 = "Ketika sepertinya semua akan lenyap, Fleur memerintahkan robot raksasa yang baru dikembangkannya dan menanggung beban dari dampak meteorit dengan tangannya! Kekuatan aneh macam apa ini?",
  str_book_info3068 = "Krisis telah dihindari. Fleur memerintahkan Rediesel Steel MkV-nya untuk berdiri di depan semua orang dan memblokir gelombang yang akan melanda.",
  str_book_info3069 = "Selama pertunjukan terakhir, tim Colossus kalah di posisi yang kurang menguntungkan di hadapan kekuatan Raja dan Caroline yang tangguh. Caroline dengan bangga mengungkapkan rahasianya kepada Beryl, dan Beryl, yang telah mengetahui kebenaran dari Raphael, melawan dengan sekuat tenaga.",
  str_book_info3070 = "Setelah menembus sihir musuh sendirian, Beryl menggunakan seluruh kekuatannya untuk melancarkan serangan terakhir dan mengalahkan Raja dan Caroline dengan bantuan teman-temannya.",
  str_book_info3071 = "Di gurun yang gersang, berdiri sebuah bangunan baja Illumina—Undercity 24 Station. Menurut laporan kami, bangunan ini paling sering digunakan sebagai tempat pelatihan bagi orang baru, dan juga digunakan sebagai pusat transportasi, yang berisi gudang dan fasilitas lainnya.",
  str_book_info3072 = "Pemimpin yang kuat dari Eclipsite meledak hingga berkeping-keping. Pada saat itulah semua orang memikirkan hal yang sama—sudah waktunya melawan!",
  str_book_info3073 = "Officer Brent memimpin para prajurit untuk melawan Eclipsite. Namun, sebuah tentakel tiba-tiba menyeruak dari tanah dan menusuk dadanya.",
  str_book_info3074 = [[
Ada suatu masa ketika Gram tidak bisa menemukan cara yang tepat untuk melepas kepergian rekan-rekan seperjuangannya.
Kini dihadapkan dengan pengorbanan Brent, Gram bersumpah untuk meneruskan keyakinan kuat Brent dan berjanji untuk terus berjuang hingga menang!]],
  str_book_info3075 = "Sesosok Eclipsite raksasa dan bisa terbang yang dikenal sebagai \"Hylingerr\" menyerang Undercity 23. Penduduk Undercity 24 menghadapinya secara langsung dengan didorong oleh tekad dan kemarahan, tak tergoyahkan oleh kekuatan menakutkan lawan.",
  str_book_info3076 = "Semua orang dengan penuh semangat menunggu kabar tentang situasi perang begitu komunikasi dipulihkan. Setelah menunggu sebentar, Reinhardt, Grand Marshal dari Illumina, muncul di layar dan mengumumkan kepada semua orang bahwa Dunefire Line telah berhasil dibangun kembali dan bahwa Illumina menjadi pemenang!",
  str_book_info3077 = "Pimpinan officer menyarankan semua orang berfoto bersama sebagai kenang-kenangan sebelum meninggalkan Undercity 24. Di foto itu tampak raut wajah para prajurit yang menyunggingkan senyum, cahaya harapan abadi Brent, dan kejayaan Illumina.",
  str_book_info3078 = "Officer Brent menjelaskan target skuad Undercity 24 sejelas mungkin ketika dihadapkan dengan serangan tentara Eclipsite—yang perlu mereka lakukan hanyalah menghadapi pasukan musuh dan mempertahankan Undercity!",
  str_book_skin_info_1001 = [[
Apakah hal-hal ada di dunia karena kita memercayainya, atau kita memercayainya karena hal-hal itu ada?
Benar atau salah, fakta atau fiksi...
Apakah kastel yang Kleken sebutkan benar-benar ada di bawah laut, atau itu hanya karangannya saja?]],
  str_book_skin_info_1002 = [[
Vice berencana untuk mendapat uang tambahan saat dalam perjalanan, jadi dia mulai bereksperimen dengan sejumlah upaya yang menarik...
Karena kamu teman yang baik, kenapa tidak menyemangatinya atau mungkin memberinya saran?]],
  str_book_skin_info_1003 = [[
Karena takut pada laut, Carleen menutup matanya saat masuk ke dalam air...
Untungnya, tangan yang kamu ulurkan membuatnya berani dan akhirnya dia pun mau membuka matanya untuk melihat keindahan lautan bersamamu.]],
  str_book_skin_info_1004 = "Sebuah hadiah yang bisa membawa kebahagiaan sejati tak ternilai harganya—ini adalah filosofi Eicy.\nUntuk membalas budi atas hadiah tak ternilai harganya yang kamu berikan padanya, dia menyiapkan banyak makanan untukmu dan mengantarnya secara langsung...\nMasalahnya, hadiahnya sedikit terlalu manis bagi semua orang.",
  str_book_skin_info_1005 = [[
Mesipun kapalnya karam, Barton menolak menyerah pada kedalaman laut dan hanyut ke sebuah pulau terpencil.
Selama masih bisa bernapas, latihan harus tetap berjalan!
Barton dan dua serigala putihnya berlari di sepanjang pantai dengan peluh mengucur dan semangat pantang menyerah demi mencapai tujuan untuk menaklukkan lautan.]],
  str_book_skin_info_1006 = [[
Sembari menatap ke seberang gurun, Hiiro mengganti pakaiannya dengan seragam Illumina Military Academy lama yang kamu berikan padanya.
Wajahnya menunjukkan raut yang paling tidak biasa, selembut langit malam yang bertabur bintang.]],
  str_book_skin_info_1007 = [[
Sebuah kuburan tersembunyi di dalam lebatnya hutan.
Sharona memberitahumu bahwa ini adalah tempat peristirahatan kaumnya yang telah tiada.
Dia menekankan fakta bahwa, walaupun mereka adalah kaumnya, mereka bukan keluarganya.]],
  str_book_skin_info_1008 = [[
Vice menyalakan kembang api dupa untuk pertama kalinya dengan petunjuk Hiiro.
Percikan kecilnya bergema di sepanjang malam yang tenang dan menerangi wajah Vice yang memerah karena gembira.
Andai saja bisa begini selamanya.]],
  str_book_skin_info_1009 = [[
Saat api berkobar di sekeliling, pahlawan kita menghancurkan jendela tanpa berpikir dua kali!
Ini adalah klimaks yang luar biasa dari adegan terakhir yang menakjubkan.
Jika menyaksikannya sebagai penonton, kamu akan memberikan tepuk tangan yang menggelegar.
Sayangnya, kebetulan kamu adalah pemeran utamanya kali ini.]],
  str_book_skin_info_1010 = "Istana pasir berubah menjadi tetesan air yang memantulkan matahari terbenam dalam kaleidoskop merah muda dan merah, tetapi gambar yang indah ini tidak seindah senyumnya.",
  str_book_skin_info_1011 = [[
Seberapa pun kerasnya Pact mencoba untuk meloloskan diri dari duri-duri, cengkeramannya justru makin kuat.
Pada saat itu, kamu mendorong pintu hingga terbuka dan menyaksikan kondisinya yang menyedihkan dengan mata kepalamu sendiri.
Pact tersipu dan berteriak, "Jangan menatapku! Aku bisa menanganinya sendiri!"]],
  str_book_skin_info_1012 = [[
Tak ada jalan keluar!
Migard menyeretmu ke ruangannya.
Ada banyak tanaman ganjil dan peralatan serta bahan-bahan penelitian ilmiah di lounge yang aneh ini.
Sepertinya... itu sama sekali tidak mengejutkan.]],
  str_book_skin_info_1013 = [[
Tanaman hijau bergoyang pelan di bawah matahari tengah hari.
Helaian bulu kucing melayang-layang di udara.
Tidur nyenyak di bawah sinar matahari dan menikmati mimpi kucing yang indah.]],
  str_book_skin_info_1014 = [[
Saat jam berdentang di angka dua belas, ilusi magis dengan lembut dilucuti oleh waktu.
Gaun pesta yang indah berubah menjadi kaleidoskop kupu-kupu yang berhamburan dalam cahaya hangat.
Hingga saatnya tiba, tarian terakhir berhenti.]],
  str_book_skin_info_1015 = [[
Saat pita yang indah menari di udara, suasana musim perlahan mulai terasa.
Semangat, penantian, dan rasa gugup pun meresap.
Setelah menahan ketegangan menghitung menit dan detik, tidak ada yang bisa menyangkal kegembiraan saat itu, ketika seseorang akhirnya bisa membuka hadiah yang telah lama ditunggu-tunggu!]],
  str_book_skin_info_1016 = [[
Saat gema pesta yang jauh mendekati pantai, gema itu berhamburan oleh angin di atas Lake Mirror.
Nikinis menundukkan kepalanya untuk melihat permukaan danau...
Tapi kakaknya tidak dapat terlihat. Sebaliknya, dia dihadapkan dengan bayangan yang jelas dari dirinya sendiri.]],
  str_book_skin_info_1017 = [[
Hidup itu seperti ilusi di cermin.
Ada keinginan dan kerinduan akan sesuatu yang tidak bisa dimiliki.
Ketika gejolak meliputi pikiran, solusi terbaik adalah menjernihkan pikiran itu di tengah lautan kekalutan dan tenggelam dalam tidur yang damai.]],
  str_book_skin_info_1018 = [[
"Menyingkirkan kekhawatiran tidak sesulit kedengarannya."
Pelayan itu tersenyum berseri-seri.
"Yang kau butuhkan hanyalah tempat yang hangat, minuman panas, dan seseorang untuk mengobrol."
"Dan, tentu saja, tidur nyenyak."]],
  str_book_skin_info_1019 = "Keberanian seekor kadal! Di bawah sinar matahari yang menyilaukan dan padang pasir yang luas, Maggie muncul dengan gagah berani hingga membuat performer itu terpental. Tidak hanya mengejutkan penonton, tetapi juga meninggalkan kesan yang mendalam.",
  str_book_skin_info_1020 = "Peringatan! Eve dalam bahaya! Setelah mengenakan pakaian aneh ini, di mana pun Eve berada, setiap kali dia mengaktifkan perangkatnya, Sinsa akan segera muncul di sisinya seperti ayah yang penyayang... Eh, sebentar, maksudku seperti kakak laki-laki.",
  str_book_skin_info_1021 = "Setelah berpikir dan merenung di bawah cahaya matahari terbenam, Uriel, seperti biasa, tenggelam dalam pikirannya tentang ketiadaan. Satu-satunya hal yang bisa menyelamatkannya adalah keberadaanmu yang menemaninya. Hasilnya tidak penting, yang penting adalah waktu yang dihabiskan bersama.",
  str_book_skin_info_1022 = "Entah ini kebiasaan yang baik atau buruk... Sariel, yang mementingkan simetri dalam segala hal, lebih suka merobek stoking yang sangat bagus agar simetris.",
  str_book_skin_info_1023 = "Carleen berubah menjadi outfit yang benar-benar berbeda dari dirinya yang biasanya serius demi sebuah pesta piyama! Tetapi, jangan menatapnya karena Knight Commander juga akan panik.",
  str_book_skin_info_1024 = "Shinnosuke adalah seorang samurai dari timur. Demi memulihkan kesehatan adiknya—Eve, dia telah bersumpah untuk melenyapkan semua kejahatan. Selama perjalanannya, dia bertemu musuh bebuyutannya—Caelestite, dan bertarung sampai mati. Siapakah yang akan bertahan?",
  str_book_skin_info_1025 = "Vivian mengenakan outfit Cloud Mountain dan mengambil alih sebagai pemilik Cloud Blossom Hotel untuk sementara. Dengan bantuannya, penginapan yang biasanya sepi dipenuhi tamu. Namun, dia harus belajar untuk lebih banyak beristirahat!",
  str_book_skin_info_1026 = "Dengan mengenakan pakaian tempur khusus, Wrath tiba di Cloud Island dan memulai misi investigasinya. Hanya saja, bukankah pakaian ini sedikit mencolok? \"Ini pasti ide Hiiro!\"—kata Legion Commander Wrath.",
  str_book_skin_info_1027 = "Seorang gadis flamboyan berdiri di peron dengan payung putihnya sambil menulis keinginannya di kartu pos. Ini akan menjadi liburan yang indah jika tidak ada kejadian tak terduga yang terjadi. Tapi kurasa, hakim kepala yang dapat dipercaya selalu siaga!",
  str_book_skin_info_1028 = "Connolly, yang ingin menjadi pemandu sorak, kesulitan menyesuaikan diri dengan pakaiannya. Berkat dukungan dari orang-orang di sekitarnya, dia memutuskan untuk menaklukkan penghalang dalam pikirannya dengan menjalani \"latihan\" khusus. Namun, hujan yang turun tiba-tiba mengacaukan rencananya…",
  str_book_skin_info_1029 = "Karena satu dan lain hal, pakaian baru yang seharusnya dikenakan saat acara digantikan oleh kemeja bermotif bunga. Pada hari acara tersebut berlangsung, meski diejek akibat pakaian yang dikenakannya, Istvan menampilkan performa yang sempurna sehingga membuat lawannya diam membisu.",
  str_book_skin_info_1030 = "\"Kekuatan belaka tidak akan mampu menggantikan kuasa keadilan.\" Tak perlu mengikuti peraturan pertandingan yang tak berarti atau memedulikan peringkat palsu. Berikan yang terbaik dan pergilah dengan sikap santai.",
  str_book_skin_info_1031 = "Taki memimpin klasemen saat balapan memasuki tahap Umbraton Group Match. Tak mau kalah, lawan Taki menggunakan \"senjata mematikan\" atau semacamnya untuk membuat mobilnya tak ubahnya menjadi barang rongsokan…",
  str_book_skin_info_1032 = "Louise sedang bersantai di rerumputan sembari menikmati teh sore yang nikmat bersama \"majikannya\". Menurutnya, hidup seorang pelayan seharusnya penuh kebahagiaan dan kepolosan—itulah yang dikatakan Lita kepadanya.",
  str_book_skin_info_1033 = "\"Dag Dig Dug…\" Peristiwa itu membuat jantung Bethel berdegup kencang seperti genderang perang. Apakah itu akibat rasa takut akan bahaya atau perasaan gembira berkat datangnya inspirasi? Atau, perasaan itu malah disebabkan oleh sosok pujaan hati? Mungkin… kita bisa mengetahui secercah jawabannya dari novel karya Bethel.",
  str_book_skin_info_1034 = [[
Fleur mengambil roti yang baru matang dari oven, menggigit roti itu sambil menurunkan kepalanya, lalu mengunyahnya dengan perlahan. Tiba-tiba, dia terdiam mematung, air mata tergenang di matanya...
"Terima kasih karena telah membantuku menemukan cita rasa hangat itu."]],
  str_book_skin_info_1035 = "Ini bukan lelucon. Kuulangi, ini bukan lelucon! Ini adalah latihan taktis pelayan mendadak. Tahanan yang menyelinap masuk ke wastu akan diadili dan dikurung di penjara. Seluruh pelayan, termasuk Head Maid, menjalankan latihan dengan penuh percaya diri.",
  str_book_skin_info_1036 = "Kebanyakan orang menganggap hal-hal yang lapang dan melamun itu menenangkan, dan Leona tidak terkecuali. Dia menemukan ketenangan pikiran yang langka ketika dikemas oleh gelembung raksasa, yang mungkin merupakan keadaan pikiran yang telah lama dia cari.",
  str_book_skin_info_1037 = "Ada sesuatu tentang dirinya yang mempesona dan mempesona seperti permata. Saksi merasa sulit untuk menentukan dengan tepat sumber pesonanya.",
  str_book_skin_info_1038 = "Kalau ada penduduk pulau yang melakukan kejahatan lalu tak ada seorang pun yang mengindahkan keluhan korban, si korban bisa menumpahkan kesedihannya ke laut, yang kemudian akan mengutus utusannya untuk menegakkan keadilan. Kali ini, utusannya adalah...",
  str_book_skin_info_1039 = "Menambatkan \"pelangi\" di kotak kayu agar keindahannya hanya bisa dinikmati dirimu sendiri adalah tindakan yang sangat kejam lagi egoistis. Kalau kau benar-benar ingin mengapresiasi keindahan pelangi, biarkan pelangi itu menari-nari dengan bebas.",
  str_book_skin_info_1040 = "Air yang jernih dan makhluk air yang berenang bebas... Saat pandangannya terpaku pada mereka, tampaknya Gronru bisa melupakan identitasnya dan permainan yang dulunya sangat ia sukai. Saat ini, ia hanyalah gadis kecil yang senang karena sesuatu yang selama ini hanya ada di pikirannya bisa dilihatnya secara langsung.",
  str_book_skin_info_1041 = "Berenang di gurun, katamu? Tidak ada yang tak mungkin! Anggota Rediesel Wrench mengadakan festival air di Oasis. Dan pengiriman permintaan Azure yang tepat waktu membawa suasana pesta ke tingkat yang baru.",
  str_book_skin_info_1042 = "\"Saya harus mengambil setiap kehidupan tanpa berpikir dua kali.\" T-Tunggu, apa ini? Menodongkan pistol ke teman lama?! Apa yang kamu lakukan, Charon?! Sorot matanya memberitahuku bahwa dia tidak sedang bermain-main...",
  str_book_skin_info_1043 = "\"Yang hidup mengatakan seribu kebohongan, tetapi orang mati tidak mengatakan apa-apa selain kebenaran. Sayang sekali tidak ada yang bisa mendengar suara mereka.\" Mengabaikan pandangan ke samping dan bisikan orang lain, Sikare membantu mengungkap kebenaran untuk memberikan suara kepada almarhum.",
  str_book_skin_info_1044 = "Meskipun dia bukan anggota Federasi Illumina, seragam sheriff Illumina Hedy yang baru membuatnya percaya diri dan merasa berkewajiban. Dengan demikian, bahkan pidatonya mengumpulkan rasa hormat dan kekaguman dari massa.",
  str_book_skin_info_1045 = "\"Ini adalah kekecewaan yang lebih besar dari yang kukira...\" Bahkan di tempat berbahaya yang penuh dengan penjahat, kekuatan Revy membuatnya berdiri jauh di atas yang lain. Ketika seseorang begitu tak terkalahkan dalam kekuatan, kurangnya persaingan terkadang menjadi sepi.",
  str_book_skin_info_1046 = "\"Bos, ini untukmu.\" Dengan wakilnya dan anggota lainnya, Paloma terlihat seperti pemimpin geng. Di bawah pandangan sekilas semua orang, dia sudah memikirkan bagaimana menanggapi permintaan pengunjung.",
  str_book_skin_info_1047 = "Meskipun Shaya juga menunjukkan sisi keras kepala dan girlish dalam cerita, sekarang dia fokus, bertanggung jawab, dan sangat bertekad, sama seperti Bethlehem, dan menawan dengan cara yang berbeda.",
  str_book_skin_info_1048 = "Kerahkan dirimu, semuanya, karena The Punisher ada di sini! Hukuman dalam bentuk lampu yang berkedip dan guntur yang nyaring menemaninya saat dia melakukan rap di depan Anda! Di bawah pengawasannya yang tajam, tidak ada yang bisa lolos!",
  str_book_skin_info_1049 = "\"Karya ini didedikasikan untuk semua penonton.\" Musik memberi mereka kehangatan dan berkah di malam musim dingin ini. Dan untuk anggota audiensi khusus, itu juga membawa pengakuan dan dorongan.",
  str_book_skin_info_1050 = "Untuk mendapatkan keuntungan, Siobhan menghitung data semua kontestan dan dengan cepat merumuskan strateginya sendiri—untuk membangun pesonanya dengan menggunakan pakaian dan riasan serta mendominasi audisi.",
  str_book_skin_info_1051 = "aromatik? Terlalu serius? Mungkin sikapnya hanya kedok. Pittman menunjukkan sisi lembutnya ketika dua hati merindukan satu sama lain, dan merpati putih adalah buktinya.",
  str_book_skin_info_1052 = "Ksatria Petir yang terkenal memenuhi namanya dengan menyerang \"musuh\" dengan sambaran petir dalam sekejap mata. Namun, yang mengejutkannya, pria itu menyatakan cintanya pada Michael secara tiba-tiba ...",
  str_book_skin_info_1053 = "Dia adalah pemilik salon sekaligus bankir dan peserta permainan. Jeno sekarang mengerti aturan di sini. Setelah itu, dia menunjukkan kepada lawannya yang tercela sihir yang sebenarnya, menciptakan keajaiban yang mengirim kartu Joker ke tempat yang seharusnya.",
  str_book_skin_info_1054 = "\"Kalian semua—kalian semua ditahan!\" Ketika berhadapan dengan tersangka yang cukup bodoh untuk mencoba menguntit adiknya, Dayna memilih solusi yang paling langsung dan efektif—menangkap semua orang yang hadir dan tidak membiarkan satu pun dari mereka pergi.",
  str_book_skin_info_1055 = "Mungkinkah kehadiran yang tidak dapat diabaikan itu mengintai di belakang Fia dalam kegelapan benar-benar menjadi naga...? Setelah cukup tenang, dia menyadari itu hanyalah semacam alat... tapi siapa yang mengendalikannya?",
  str_book_skin_info_1056 = "Cara terbaik untuk berurusan dengan orang yang benar-benar hina adalah dengan menggunakan trik kotor mereka sendiri untuk melawan mereka — beri mereka rasa obat mereka sendiri. Dan ketika mereka akhirnya menyadari betapa berbahaya dan kejinya mereka, itu sudah terlambat.",
  str_book_skin_info_1057 = "Di tengah lautan bunga, yang jatuh Cuscuta menjerat penjahat jahat dan menyeretnya ke jurang maut, sementara wewangiannya menjadi lagu pemakaman bagi orang berdosa.",
  str_book_skin_info_1058 = "\"Jangan lari dariku.\" Eicy berkata dengan senyum polos, saat dia dengan tenang melewati kerumunan yang panik. Meski menjadi dalang di balik itu semua, dengan caranya sendiri, dia melihatnya sebagai tindakan belas kasihan.",
  str_book_skin_info_1059 = "Ternyata mantra terlarang yang tertulis di grimoire sebenarnya adalah resep masakan yang enak. Bahan-bahan yang tidak biasa berpadu secara harmonis, menciptakan rasa luar biasa yang memberikan esensi ilahi bagi mereka yang mencicipinya.",
  str_book_skin_info_1060 = "Tidak semua yang memiliki kekuatan besar itu jahat. Itu semua tergantung pada bagaimana kekuatan itu digunakan. Untuk melindungi kepolosan anak-anak, Gabriel membuat keputusan tegas dan menemukan motivasi untuk bertahan.",
  str_book_skin_info_1061 = "Tampaknya Rinne meminta bantuan teman-temannya setelah terluka dan berjanji untuk membayar mereka dengan baik sesuai dengan kebiasaan Cloud Island. Namun, apakah orang ini benar-benar Rinne?",
  str_book_skin_info_1062 = "Paloma tidak peduli tentang pendapat orang lain dan tidak pernah repot-repot dengan konvensi duniawi. Dia hanya dengan santai merasakan suasana pantai, dengan percaya diri memamerkan penampilannya, saat pesonanya menyebar dengan anggun.",
  str_book_skin_info_1063 = "Ketika kamu mengajukan permintaan pada dandelion yang utuh lalu meniupnya, permintaanmu akan terwujud saat biji dandelion pertama mendarat. Dia berbisik dalam pikirannya, dan mengamati bulu putih itu. Pada saat itu juga, permintaan sudah menjadi kenyataan.",
  str_book_skin_info_1064 = "Eksplorasi reruntuhan sarat dengan bahaya, terutama di bawah air, di mana rumput air yang tampaknya tidak berbahaya pun bisa menjadi jerat mematikan. Untungnya, Florine ada di sini, memastikan skenario seperti itu tidak akan terjadi.",
  str_book_skin_info_1065 = "Ombak membawa botol hanyut ke tangannya. Tanpa penerima yang dimaksud, botol hanyut bukanlah sarana untuk menyampaikan pesan, tetapi melambangkan keinginan seseorang. Namun pada saat ini, tampaknya ombak bukan lagi sekadar ombak, melainkan anggota dari Courier Union yang terhormat.",
  str_book_skin_info_1066 = "Para naga es meluncur di udara kering, membawa angin sejuk ke sini, dan di permukaan laut, kristal-kristal dingin yang berkilau mulai mengembun... Hanya Queen yang maha kuasa dari Northland yang bisa menciptakan pemandangan indah dan megah seperti itu di pantai yang panas di puncak musim panas.",
  str_book_skin_info_1067 = "Ubur-ubur yang mengambang ini tampak luar biasa di mata semua orang, tetapi laut berpendar yang mereka bentuk di sini dan sekarang bahkan lebih fantastis daripada yang bisa dilihat dalam dongeng manapun.",
  str_book_skin_info_10045 = "She's the lofty, distant, and unsmiling Chief Judge to everyone else. But right now, she's showing a completely different side of her, one that she keeps well hidden beneath her mask...",
  str_book_skin_info_10046 = [[
Saat hujan mereda dan matahari muncul, keduanya berjalan-jalan di sepanjang pantai yang basah.
Melihat awan gelap yang perlahan menghilang, sinar matahari menyinari laut biru dan pasir emas.
Satu-satunya hal yang lebih indah dari ini adalah jika mereka juga bisa melihat pemandangan cantik ini.]],
  str_book_skin_info_10047 = [[
Lingkungan yang terus berubah, bunyi jam yang menyeramkan, dan ilusi mendadak ini...
Sanae merasa sangat ketakutan.
Hanya dengan tetap dekat dengan Navigator, dia memiliki keberanian untuk terus melangkah maju.]],
  str_book_skin_info_10048 = [[
Nina masih merasa bahwa banyak ide-idenya belum terwujud setelah dia mengambil beberapa seri foto.
Dia memutuskan untuk mengikuti saran Navigator dan beristirahat setelah bekerja keras, tetapi kegalauan masih menghantuinya.]],
  str_book_skin_info_10049 = "Connolly keluar dari ruang ganti sambil menyesuaikan gaunnya, ekspresi cemas terpancar di wajahnya. Meskipun dia sangat menyukai pakaian ini, dia harus mengenakannya untuk menyambut yang lain, dan hanya membayangkan tatapan Navigator yang tertuju padanya membuatnya gugup. Sekarang, yang dia inginkan hanyalah menemukan sudut gelap untuk bersembunyi.",
  str_book_skin_info_10050 = "Saat senja menyelimuti, Anda berkumpul di sekitar api unggun, merenungkan pengalaman baru-baru ini. Anda diam-diam mendengarkan Gram berbagi cerita tentang para prajurit muda yang ia temui setelah menjadi instruktur: Beberapa menciptakan jalan mereka menuju kemuliaan, sementara yang lain mengalami ajal yang tak terduga dalam pertempuran terakhir.",
  str_book_skin_info_10051 = "Saat Vacuum Cleaner Eclipsite mengaum hidup, Revy dengan cepat mengalahkan semua musuh di depan. Kemudian, sesuai permintaan Gronru, Revy segera melakukan pose menawan, dan Gronru memanfaatkan momen itu untuk menyelesaikan pengambilan gambar iklan.",
  str_book_skin_info_10052 = "Mereka akhirnya menggali lubang, dan Ciel berhadapan langsung dengan kamu dan Gronru. Meskipun tahu bahwa Ciel akan aman, Gronru menawarkan pelukan penghiburan untuk meredakan kegugupannya. Dengan emosi Ciel yang tenang, dia akan melanjutkan untuk memandu tim dalam misi yang akan datang.",
  str_book_skin_info_10053 = [[
Mendengar suara campuran para pelaut yang berteriak dan kapal-kapal yang meninggalkan pelabuhan, Dantang dapat merasakan antusiasme para pelaut untuk berpetualang dari tempat dia berdiri di sebuah paviliun.
Namun, saatnya bagi mereka untuk kembali, beberapa kapal ini kembali ke pelabuhan dengan emas, perak, harta karun, dan cerita eksotis, sementara beberapa kapal tidak pernah kembali. Itulah mengapa Dantang diam-diam berdoa untuk kapal-kapal yang berlayar ke laut dari pelabuhan sambil memegang pegangan merah dan menyaksikan keberangkatan mereka.
Meskipun berlayar ke laut adalah petualangan dan perjalanan bagi yang berani, jangan lupakan bahwa selalu ada seseorang yang mengawasi dari belakang Anda, menunggu orang yang mereka cintai untuk kembali.]],
  str_book_skin_info_10054 = "Tidak disangka oleh Sariel bahwa kejadian terpelesetnya tidak hanya menyelesaikan masalah di rumah judi, tetapi juga menyebabkan hadiah komisinya hilang begitu saja. Apakah ini keberuntungan atau kesialan? Terlepas dari itu, Sariel merasa beruntung bisa menghadapi krisis bersama Navigator.",
  str_book_skin_info_10055 = [[
Menghunus pedang mudah, tapi menyumpitnya sulit, karena hati, bukan tangan, adalah kunci penggunaan pedang. Bahkan bilah paling tajam pun tak akan bisa mengalahkan hati seperti ini, karena dedaunan bambu sudah jatuh sebelum pikiran itu muncul...
Pedang belum dihunus.]],
  str_book_skin_info_10056 = [[
"Diberkati oleh takdir, Gadis Naga membawa kabar baik saat ia turun ke dunia."
"Gelombang samudra yang luas terasa samar, seolah-olah tertutup kabut."
"Gadis Naga, pemberian dari langit, membawa berkah tak terhitung untuk semua orang."
"Seperti bulan muda yang perlahan tumbuh penuh, atau matahari yang bersinar terang dalam kenaikannya."
"Gadis Naga, pemberian dari langit, membawa berkah tak terhitung untuk semua orang."
"Seperti bulan muda yang perlahan tumbuh penuh, atau matahari yang bersinar terang dalam kenaikannya."]],
  str_book_skin_info_10057 = "Sariel begitu penuh kegembiraan, dia tidak menyadari bahwa pakaian yang disiapkan untuknya oleh toko itu sangat tidak simetris sampai dia memakainya. Sebagai seseorang dengan kecenderungan obsesif-kompulsif, seketika rasanya seperti jarum menusuk seluruh tubuhnya, dan dia ingin merobek kain yang sangat tidak seimbang itu segera. Namun, dia hanya berani menarik ujung roknya untuk meluapkan ketidakpuasannya karena toko itu akan membuatnya membayar kerusakan.",
  str_book_skin_info_10058 = "Prajurit duyung di belakang Tianxian mengejarnya dengan putus asa untuk mencopot pakaian mewah Istana Naga darinya dan melemparkannya ke penjara. Tianxian tidak dalam suasana untuk berdebat, dan hal terpenting baginya sekarang adalah melarikan diri dari Istana Naga. Namun, bagi orang-orang yang telah mengalami suka duka hidup, masuk ke istana itu mudah, tetapi keluar adalah hal yang sepenuhnya berbeda...",
  str_book_skin_info_10059 = "Kue khusus hari raya yang baru dipanggang ini mengeluarkan aroma yang memikat, dan panas yang lembut cukup untuk mengusir dingin di rumah. Kue-kue ini dipanggang oleh anak-anak panti asuhan, dan Lilica membagikannya dengan Anda karena dia berpikir Anda pantas mendapatkan setengah kredit untuk penampilan yang sukses. Semoga May kue ini mengusir dingin dan membawa Anda keberuntungan di cuaca dingin ini.",
  str_book_skin_info_10060 = "Dengan kecepatan kilat, Hiiro menghunus pedangnya dan mengubah penyerang menjadi debu, tidak meninggalkan tanda keberadaan mereka. Gaun elegannya membuat kehadirannya yang mengagumkan menjadi lebih indah.",
  str_book_skin_info_10061 = "Cahaya tenang dari api unggun memberikan warna aneh pada wajah Hiiro. Mungkin itu adalah warna bunga sakura yang mekar lebih awal di tempat yang jauh, atau warna emosi kuat yang wanita cantik ini terlalu malu untuk ungkapkan.",
  str_book_skin_info_10062 = "Pollux menceritakan kepada Anda bagaimana krisis di masa lalu mendorongnya untuk menjadi pelindung. Namun, dia tidak ingin terpaku pada kenangan tersebut, karena dia mengantisipasi untuk menciptakan masa depan yang lebih baik bersama Anda.",
  str_book_skin_info_10063 = "Meski Areia benar-benar menikmati waktu indah bersamamu dalam mimpi, mereka ditakdirkan untuk menghilang. Kenyataan telah membuatnya bingung. Setelah berendam dalam sinar matahari yang asli dan menghirup angin laut yang menyegarkan, Areia akhirnya mengerti bahwa kebaikan dan kebahagiaan selalu ada di sekelilingnya.",
  str_book_skin_info_10064 = "Xuan Ji memberikanmu payung ini, serta mimpi yang diwakilinya. Entah itu tanah yang jauh atau bintang-bintang yang selalu tampak jauh, tidak ada yang benar-benar di luar jangkauan selama kamu menginginkannya.",
  str_book_skin_info_10065 = "Setiap kalimat, setiap kata, setiap karakter dari masa lalu berpotensi menjadi tanda yang ditinggalkan oleh pendahulu kita dalam perjalanan mereka menuju kebenaran. Apa yang membentuk setiap karakter dan apa makna yang mungkin bisa dipegang—semua jawaban terletak dalam setiap goresan.",
  str_book_skin_info_10066 = "Apa yang lebih nyaman daripada berbaring di sini dalam kebahagiaan?\nTidak ada tugas yang harus diselesaikan, tidak ada pertempuran yang harus dihadapi, dan tidak perlu mencari makna untuk apapun — satu-satunya makna dari momen ini hanyalah untuk melepaskan diri dan menikmati.\nLihat, bahkan burung merpati putih yang terbang di luar jendela saya setuju.",
  str_book_title_skin_50001 = "Day at the Aquarium",
  str_book_skin_info_50001 = "Mana yang lebih dulu muncul, pakaian ini atau permainan yang menyertai pakaian ini? Tak perlu dipikirkan. Yang penting, Gronru menyiapkan pakaian khusus liburan ini dan dia langsung memasuki mode berlibur begitu mengenakannya, meskipun dia hanya berlibur ke akuarium, bukan pantai.",
  str_book_title_skin_50002 = "Fluffy Serendipity",
  str_book_title_skin_50003 = "Lahir untuk Bertindak",
  str_book_title_skin_50004 = "Pelukan Melody yang Manis",
  str_book_title_skin_50005 = "Imajinasi Mabuk",
  str_book_saiji_info_20001 = "Dalam ingatan Eve, ini adalah rumah bahagianya. Tetapi ada yang hilang. Mungkin ada sesuatu yang terlupakan, atau mungkin seseorang yang hilang...",
  str_book_saiji_info_20002 = "Kenangan akhirnya telah terhapus, dan Eve telah bersatu kembali dengan keluarga tercintanya. Harapan dan kebahagiaan, berkembang di bawah sinar matahari, telah menjadi bunga putih yang mekar.",
  str_book_saiji_info_20003 = "Eve \"terbangun\" dari mimpi yang intens, dan menemukan dirinya berada di lingkungan yang familiar, namun sekaligus asing. Apakah ini kamar miliknya?",
  str_book_saiji_info_20004 = "Sebuah crawler baja raksasa merayap di puncak gunung. Siapa pencipta mesin seperti itu? Dan untuk tujuan apa itu dibangun? Sebuah perasaan deja vu melanda Eve; pemandangan itu terasa familiar, namun dia tidak dapat menentukan di mana dia pernah mengalaminya sebelumnya...",
  str_book_saiji_info_20005 = "Saat kehancuran yang semakin dekat mengancam Eve, perisai bunga putih yang akrab dan sulur yang kokoh muncul secara misterius. Darimana mungkin mereka bisa tumbuh?",
  str_book_saiji_info_20006 = "Dua Eve akhirnya bergandengan tangan, siap untuk menghadapi kenyataan yang sebenarnya.",
  str_book_saiji_info_20007 = "Dunia yang terdistorsi menghilang, meninggalkan Eve dengan perasaan lega. Meskipun jalur ke depan mungkin dipenuhi dengan rintangan, jalur tersebut juga bersinar dengan potensi tak terbatas.",
  str_book_saiji_info_20101 = "Cahaya matahari menembus kaca berwarna, menusuk ruangan yang redup dan sunyi, menciptakan rentetan warna yang mempesona. Cahaya itu lembut menyentuh kelopak mata Irridon, dan dia membuka matanya. Saat itulah dia melihatnya, pantulan seorang wanita di cermin.",
  str_book_saiji_info_20102 = "Irridon tahu bahwa orang di cermin bukan dirinya, tetapi entah mengapa, dia merasa takdirnya erat kaitannya dengan pantulan itu. Kemudian nyala lilin menyala, menerangi gambar seorang biarawati yang murni dan tenang di dinding.",
  str_book_saiji_info_20103 = "Irridon mengingat kembali identitas sosok di cermin dan akhirnya mengingat siapa dirinya. Lilin di sisi lain menyala, menampilkan gambaran yang serius dan megah dari Chief Judge di lukisan dinding.",
  str_book_saiji_info_20104 = "Saat menatap bayangannya di kolam, Irridon tiba-tiba merasa ingin merenung... Apa yang membuatnya menjadi dirinya saat ini? Apakah pantulan di kolam itu benar-benar citra yang ingin dia capai?",
  str_book_saiji_info_20105 = "Wanita berpakaian hitam di depannya melompat ke aksi, diikuti oleh banyak duri menjulang dari segala arah. Irridon mengerti bahwa wanita itu membawa kegelapan yang lebih tajam dan lebih hitam di hatinya daripada duri-duri ini.",
  str_book_saiji_info_20106 = "Dalam hal ini, Irridon tidak bisa diam saja dan menyaksikan wanita di hadapannya melakukan kesalahan yang sangat fatal.",
  str_book_saiji_info_20107 = "Mengalahkan diri sendiri bukanlah hal yang mudah, tetapi Irridon akhirnya berhasil melakukannya.",
  str_book_saiji_info_20108 = "Percobaan berat ini akhirnya berakhir. Meskipun jalan ke depan masih panjang, Irridon tidak akan tersesat lagi.",
