  str_book_title_skin_10068 = "Undangan Mabuk",
  str_book_skin_info_10068 = [[
"Waktu seorang penyihir sangat berharga dan aku tidak bisa menunggu, tsk-tsk."
Setelah meminum ramuan ajaib, Uriel tiba-tiba menjadi proaktif, tidak hanya memojokkan Anda tetapi juga mencoba sesuatu yang bahkan lebih mengerikan...]],
  str_book_title_skin_10069 = "Lonceng di Senja",
  str_book_skin_info_10069 = "\"Saya sendiri baru menyadari—dan itu benar-benar baru saja—bahwa kehampaan bisa diisi.\"\nPanas api menyamarkan sosok sang penyihir. Tapi mana di antara dirinya yang sedang mengaku padamu sekarang?",
  str_book_title_skin_10067 = "Sensibilitas Axelia",
  str_book_skin_info_10067 = "Sebuah perasaan magis telah menyerang Axelia, mempertemukan dirinya yang retak dengan mawar yang terkurung dalam toples kaca. Lonjakan emosi yang tak dapat dijelaskan ini sebenarnya menandakan perubahan yang sedang berkembang dalam pola pikirnya.",
  str_book_title_skin_10070 = "Tersayang",
  str_book_skin_info_10070 = "\"Itu adalah ladang gandum! Penuh dengan biji-bijian yang berayun emas, dan aku berdiri di dalamnya! Di sampingku ada seorang wanita lembut yang wajahnya tidak jelas bagiku, tetapi dia tersenyum padaku. Banyak anak-anak berlarian di sekitar kami... Tawa mereka bergema melalui ladang seperti lagu.\"",
  str_book_title_skin_10071 = "Saksi Idol Naga",
  str_book_title_skin_10072 = "Tidur Siang Robyn",
  str_book_skin_info_10071 = [[
"Mungkin sedikit sombong jika saya mengatakannya, tapi saya benar-benar berharap bisa menjadi seseorang yang bisa kamu andalkan."
Di bawah saksi patung naga, kamu mengajukan undangan kepada Sharona.]],
  str_book_skin_info_10072 = "Tersesat dalam dunia buku, Robyn mengangguk tertidur di meja. Sinar matahari tengah hari sangat terik, tetapi tidurnya tidak terganggu.",
  str_book_info1108 = "Keinginan",
  str_book_info1109 = "Hancurkan Kegelapan",
  str_book_info1110 = "Surga",
  str_book_info1111 = "Haven - Beacon",
  str_book_info1112 = "Janji di Puncak Bukit",
  str_book_title1108 = "Membawa tugas yang tak terkatakan, dia berlutut di depan altar, kesedihannya tak terucapkan tetapi sangat terasa, menawarkan doa yang penuh semangat kepada yang ilahi. Ritual misterius dan menyentuh ini terbentang seperti sebuah karya agung yang melankolis.",
  str_book_title1109 = "Di tengah kegelapan, dia melompat seperti kilat, tombaknya menusuk tanpa ampun ke tengkorak musuh. Dengan keganasan dan kekuatan yang liar, dia mengguncang bumi, matanya membara dengan kebencian balas dendam yang membakar lawan-lawannya.",
  str_book_title1110 = "Dipimpin oleh roh gunung, kekuatan alam mengalir ke dasar, dan gugusan cahaya yang mengalir meledak dari tunggul pohon, menerangi altar yang luas. Dengan demikian, roh-roh yang lama diam terbangun.",
  str_book_title1111 = "Dalam sekejap, tiga pohon pinus salju kuno tumbuh menjadi pohon yang menjulang tinggi seperti mercusuar, cahayanya yang berkilau menerangi seluruh gua, dengan sinar yang paling lembut meresap ke tombak Tiare.",
  str_book_title1112 = [[
"Untuk mendirikan mercusuar di sepanjang jalan di depan."
Banner yang berkibar menjadi saksi dan memberi semangat untuk mereka, membawa janji mereka ke tanah yang jauh.]],
  str_book_title_skin_10073 = "Cahaya Fluorite",
  str_book_skin_info_10073 = "Kamu mengobrol sampai larut malam dengan Fleur tentang mineral ketika bijih tersebut memancarkan cahaya redup—tunggu, kenapa masih hangat? Melihat dari wajah Fleur, apakah dia sedang demam?",
  str_book_title_skin_10074 = "Dormitory Games",
  str_book_skin_info_10074 = "\"Sekarang setelah aku menangkapmu, kamu harus menyentuh hati di atas meja untuk bebas!\"",
  str_book_title_skin_10075 = "Malam Bintang yang Tak Tertidur",
  str_book_skin_info_10075 = "\"Dengan kamu di sisi saya, tidak peduli seberapa gelap, saya rasa saya tidak perlu takut akan apapun!\"",
  str_book_title_skin_10077 = "Sleeping Beauty & Pangeran",
  str_book_skin_info_10077 = "\"Apakah aku masih bermimpi? Semuanya terasa begitu nyata, dari kehangatanmu hingga nafasmu...\"",
  str_book_title_skin_10078 = "Ayo Kita Lakukan",
  str_book_skin_info_10078 = "Pintu tiba-tiba terbuka, menghentikan langkah ragu gadis itu. Dalam hal ini, dia hanya bisa menelan pil pahit dan berjalan maju dengan kepala tegak. Gadis itu menggigit bibirnya, bertekad untuk tidak membiarkan siapa pun melihat kebingungannya dan ketidakberdayaannya.",
  str_book_title_skin_10079 = "Tarian Siput Sungai Gadis Naga",
  str_book_skin_info_10079 = "\"Dengan melakukan tarian sakralnya di sini, siput-siput akan melakukan apa yang saya perintahkan karena penghormatan.\"",
  str_book_title_skin_10080 = "Binatang yang Dikurung",
  str_book_skin_info_10080 = "Hydrad telah menyusup ke dalam barisan mereka sendirian dan mengandalkan kamu untuk datang dengan bala bantuan.",
  str_book_title_skin_10081 = "Dewa Kecil",
  str_book_skin_info_10081 = "\"Penawaranmu sangat menyenangkan hatiku. Ucapkan permintaanmu, dan aku akan mengabulkannya untukmu.\"",
  str_book_title_skin_10082 = "Warna-warna Berkembang",
  str_book_skin_info_10082 = "\"May seluruh keindahan dunia menari atas namamu, dan May kepemimpinan bijakmu berkembang selama seribu tahun.\"",
  str_book_title_skin_10084 = "Pengamat Yingel",
  str_book_skin_info_10084 = "\"Seperti yang bisa kamu lihat, saya sedang mengamati Rediesel Wrench di habitat alaminya.\"",
  str_book_title_skin_10085 = "Bertampil bersama Barbara",
  str_book_skin_info_10085 = "Konser Barbara dimulai dengan gemilang! \"The Last Caelestite\" benar-benar debut bersamanya?",
  str_book_title_skin_10086 = "Jeriah di Pantai",
  str_book_skin_info_10086 = "\"Apakah itu kamu atau lingkungan kita... Semuanya baru bagiku.\"",
  str_book_title_skin_10087 = "Bintang Banquet",
  str_book_skin_info_10087 = "\"Mendekatinya sangat diterima, tetapi saya meminta Anda untuk bersikap dengan sedikit lebih bermartabat.\"",
  str_book_title_skin_10088 = "Siluet dari Enlightened Illumination",
  str_book_skin_info_10088 = "\"Sebagai Grand Marshal dari Federasi Illumina... Aku bersumpah untuk mengawasi segalanya.\"",
  str_book_title_skin_10090 = "Tidak menyerah pada Waktu",
  str_book_skin_info_10090 = "\"Anak-anak dari 2nd Legion... Apakah kalian telah menjadi bintang yang menerangi jalan orang lain?\"",
  str_book_title_skin_10091 = "Kembar Bunga Putih",
  str_book_skin_info_10091 = "\"Kami sangat mirip; bahkan orang tua kami pun kesulitan membedakan kami...\"",
  str_book_title_skin_10092 = "Sprint Pasir",
  str_book_skin_info_10092 = "\"Pistol ini sekarang menembakkan air bukan api. Seandainya... hanya jenis kesenangan ini yang bisa bertahan selamanya. Seekor elang masih bisa terbang tinggi meski cakarnya disimpan.\"",
  str_book_title_skin_10095 = "Hari Malas Ryza",
  str_book_skin_info_10095 = "\"Kamu memanggilku? Ada apa?\"",
  str_book_title_skin_10096 = "Kembang Api di Matanya",
  str_book_skin_info_10096 = "\"Kembang api mungkin singkat, tetapi mereka akan selamanya berkedip di hati saya.\"",
  str_book_title_skin_10097 = "Dignitari yang Basah Kuyup",
  str_book_skin_info_10097 = "\"Maksud saya, jika kamu bertanya dengan tulus seperti sebelumnya, saya, seorang bangsawan, mungkin bisa menyisihkan waktu untuk bersenang-senang denganmu.\"",
  str_book_title_skin_10099 = "Pertemuan Tak Terduga: Bola Salju",
  str_book_skin_info_10099 = "\"Silakan ikuti arah yang saya tunjukkan. Rasakan hanyutan ombak. Jangan takut, saya akan memegang tanganmu.\"",
  str_book_skin_info_laisha = "Ryza's Lazy Day",
  str_book_title_skin_laisha = "\"! Ada apa?\"",
  str_book_skin_info_laisha1 = "The Fireworks in Her Eyes",
  str_book_title_skin_laisha2 = "\"Fireworks may be brief, but they'll forever flicker in my heart.\"",
  str_book_info_laisha1 = "Bertemu di Tempat yang Dilanda Ombak",
  str_book_title_laisha1 = "\"Saya pikir kita sedang bermain, bukan? Lebih baik bergerak, atau saya benar-benar akan memberimu pelajaran! Hah!\"",
  str_book_info_laisha2 = "Mengumpulkan Pikiran",
  str_book_title_laisha2 = "\"Bagaimana? Apakah kamu bisa merasakan tekad kami sekarang?!\"",
  str_book_info_laisha3 = "Petualangan Baru! Berlayarlah!",
  str_book_title_laisha3 = "Pulau itu berbaring diam di dasar laut, bersama dengan bukti kejayaan masa lalunya. Sekarang, petualangan musim panas baru akan segera dimulai.",
  str_book_title_skin_10100 = "Usulan Ambisius",
  str_book_skin_info_10100 = "Mau kencan? Ingat untuk membawa cukup koin emas!",
  str_book_title_skin_10101 = "Crimson Indulgence",
  str_book_skin_info_10101 = "Raja yang Kembali dari Pesta Berdarah",
  str_book_title_skin_10102 = "Goresan Baja",
  str_book_skin_info_10102 = "Jangan tegang, minumlah satu botol larutan nutrisi dulu!",
  str_book_title_skin_10103 = "Avaricious Lachesis",
  str_book_skin_info_10103 = "\"Di bawah pesona anggun dan memikatnya, cahaya serakah berkelip. Tetap waspada, atau dia akan merampas segala yang kamu sayangi!\"",
  str_book_info1113 = "Hidup Bebas atau Mati",
  str_book_title1113 = [[
"'Hati'nya terus menyala, tak pernah lelah dalam mengejar kebebasan.
Dia akan memberikan hidupnya untuk kebenaran ini.
'Hidup bebas atau mati,' kata Lady Pepita."]]
}
